def transforms(a):
    # identity, rot90,180,270, flipH, flipV, tr, tl, tbr, tbl, plus flips of those
    res=[]
    b=a
    def rot(x):
        return [list(r) for r in zip(*x[::-1])]
    s=[a]
    cur=b; 
    q=[b]; seen={id(b)}
    while q:
        x=q.pop(); 
        y=rot(x)
        if id(y) not in seen: seen.add(id(y)); q.append(y); s.append(y)
    # mirrors
    mh=[x[::-1] for x in s]
    for x in s:
        for y in mh: res.append([[y[i][j] for j in range(len(x[0]))] for i in range(len(x))])
    return res
