# Denoise A with iterative majority filter over expanding windows; inspect resulting top-left 3x7
def denoise(X, maxiter=5):
    X=X.copy()
    for i in range(maxiter):
        Y=X.copy()
        H,W=X.shape
        for r in range(H):
            for c in range(W):
                rr0,cc0=max(0,r-2),max(0,c-2); r1,c1=min(H-1,r+2),min(W-1,c+2)
                vals=A[rr0:r1,cc0:c1].flatten().tolist()
                n,v=Counter(vals).most_common(1)[0]
                if n>=4: Y[r,c]=v
        if np.array_equal(X,Y): break
        X=Y
    return X
